input.command:
BASE="$LOCALAPPDATA/Packages/Claude_pzs8sxrjxfjjc/LocalCache/Roaming/Claude"
echo "=== config.json keys ==="
python3 -c "
import json
with open(r'$BASE/config.json', encoding='utf-8') as f:
    d = json.load(f)
def mask(v):
    if isinstance(v, str) and len(v) > 20:
        return v[:6]+'...MASKED...'
    return v
def walk(d, prefix=''):
    if isinstance(d, dict):
        for k,v in d.items():
            walk(v, prefix+'/'+str(k))
    elif isinstance(d, list):
        print(prefix, '[list len', len(d), ']')
    else:
        print(prefix, '=', mask(d))
walk(d)
" 2>&1 | head -100

